import { spawn } from "node:child_process";
import { recordDropped } from "@code-health/cli-kit/dropped-files";
import { readPathAttributes, type PathAttributes } from "./tree.ts";

/** Lines at the top of a file that are searched for a generated-code marker. */
export const HEADER_LINES = 20;

/** Bytes kept from the top of a file for that search. */
const HEADER_BYTES = 4096;

const COMMENT_LEADER = /^\s*(?:\/\/|\/\*|\*|#|--|;|%|<!--|')/;

/**
 * The markers, each tested against one line of the header that starts with a comment leader.
 * `<auto-generated` is C#, `Code generated ... DO NOT EDIT` is Go, `@generated` is written by many generators,
 * `Generated by` opens the header of protoc, thrift, flex and others, and `DO NOT EDIT` in a header comment
 * says the same in the generators' own words.
 */
const MARKERS: readonly { name: string; test: RegExp }[] = [
  { name: "<auto-generated", test: /<auto-generated/i },
  { name: "Code generated ... DO NOT EDIT", test: /Code generated\b.*\bDO NOT EDIT/ },
  { name: "@generated", test: /@generated\b/ },
  { name: "Generated by", test: /\bGenerated by\b/ },
  { name: "DO NOT EDIT", test: /\bDO NOT EDIT\b/ },
];

/** The marker the first lines of `text` carry, or undefined. A marker counts only on a line that starts with a comment leader. */
export function generatedHeaderMarker(text: string): string | undefined {
  for (const line of text.split("\n", HEADER_LINES)) {
    if (!COMMENT_LEADER.test(line)) continue;
    for (const marker of MARKERS) if (marker.test.test(line)) return marker.name;
  }
  return undefined;
}

/** Directory names whose files are vendored: third-party code kept in the repository. `node_modules` is a built-in exclude. */
export const VENDOR_DIRECTORIES: readonly string[] = ["vendor", "third_party"];

/** True for a path that has a vendor directory among its directories, at any depth. */
export function isInVendorDirectory(path: string): boolean {
  const parts = path.split("/");
  parts.pop();
  return parts.some((part) => VENDOR_DIRECTORIES.includes(part));
}

const verdicts = new Map<string, boolean>();

/** Forgets the header verdicts held for blobs. For tests. */
export function clearHeaderCache(): void {
  verdicts.clear();
}

/** The first bytes of each blob in the repository's object database, read through one `git cat-file --batch` per chunk. */
export async function readBlobHeads(repoPath: string, blobs: readonly string[]): Promise<Map<string, string>> {
  const heads = new Map<string, string>();
  const chunkSize = 256;
  for (let start = 0; start < blobs.length; start += chunkSize) {
    const chunk = blobs.slice(start, start + chunkSize);
    const stdout = await catFileBatch(repoPath, `${chunk.join("\n")}\n`);
    let offset = 0;
    for (const sha of chunk) {
      const newline = stdout.indexOf(0x0a, offset);
      if (newline === -1) break;
      const header = stdout.toString("utf8", offset, newline).split(" ");
      if (header[1] !== "blob") {
        offset = newline + 1;
        continue;
      }
      const size = Number(header[2]);
      const bodyStart = newline + 1;
      heads.set(sha, stdout.toString("utf8", bodyStart, bodyStart + Math.min(size, HEADER_BYTES)));
      offset = bodyStart + size + 1;
    }
  }
  return heads;
}

function catFileBatch(cwd: string, input: string): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    const child = spawn("git", ["cat-file", "--batch"], {
      cwd,
      env: { ...process.env, LC_ALL: "C", GIT_OPTIONAL_LOCKS: "0", GIT_CONFIG_NOSYSTEM: "1", GIT_CONFIG_GLOBAL: "/dev/null" },
      stdio: ["pipe", "pipe", "pipe"],
    });
    const out: Buffer[] = [];
    child.stdout.on("data", (chunk: Buffer) => out.push(chunk));
    child.on("error", reject);
    child.stdin.on("error", () => {});
    child.on("close", (code) => (code === 0 ? resolve(Buffer.concat(out)) : reject(new Error(`git cat-file --batch failed (${code})`))));
    child.stdin.end(input);
  });
}

export interface HeadSource {
  path: string;
  /** Git blob SHA of the file's content at the analysed revision. */
  blob: string;
}

export type HeadReader = (missing: readonly HeadSource[]) => Promise<Map<string, string>>;

/**
 * The paths whose first lines carry a generated-code marker. A blob is read once and its verdict is kept by blob
 * SHA, so a file met again, in another command of the same process or at another path with the same content, is
 * not read again. `read` supplies the first text of the blobs that are not cached: by default from the
 * repository's object database, or from the working tree for a tree that has uncommitted files.
 */
export async function generatedByHeader(repoPath: string, sources: readonly HeadSource[], read?: HeadReader): Promise<Set<string>> {
  const reader: HeadReader = read ?? ((missing) => readBlobHeads(repoPath, [...new Set(missing.map((m) => m.blob))]));
  const missing = sources.filter((source) => !verdicts.has(source.blob));
  if (missing.length > 0) {
    const heads = await reader(missing);
    for (const source of missing) {
      const head = heads.get(source.blob);
      if (head !== undefined) verdicts.set(source.blob, generatedHeaderMarker(head) !== undefined);
    }
  }
  return new Set(sources.filter((source) => verdicts.get(source.blob) === true).map((source) => source.path));
}

export interface FileClasses {
  /** Marked linguist-generated, or carrying a generated-code header. */
  generated: Set<string>;
  /** Marked linguist-vendored, or below a vendor directory. */
  vendored: Set<string>;
}

const BINARY_EXTENSIONS = new Set([
  "png", "jpg", "jpeg", "gif", "bmp", "ico", "webp", "avif", "tif", "tiff", "psd", "pdf", "zip", "gz", "tgz", "bz2", "xz", "zst", "7z",
  "tar", "jar", "war", "wasm", "bin", "dll", "exe", "so", "dylib", "a", "o", "obj", "class", "pyc", "safetensors", "onnx", "pt", "pth",
  "ckpt", "npy", "npz", "glb", "ttf", "otf", "woff", "woff2", "eot", "mp3", "mp4", "mov", "avi", "ogg", "wav", "flac", "webm", "mkv",
  "sqlite", "db", "lockb",
]);

/** True unless the extension is one that names binary content, which is never searched for a header. */
export function maybeText(path: string): boolean {
  const name = path.slice(path.lastIndexOf("/") + 1);
  const dot = name.lastIndexOf(".");
  return dot <= 0 || !BINARY_EXTENSIONS.has(name.slice(dot + 1).toLowerCase());
}

export interface ClassifyOptions {
  /** Paths that can hold a generated-code header: the code files. Default: every path that is not named like a binary file. */
  headerCandidate?: (path: string) => boolean;
  /** Reads the first text of blobs. Default: the repository's object database. */
  read?: HeadReader;
}

const noAttributes = (): PathAttributes => ({ generated: new Set(), vendored: new Set(), notGenerated: new Set(), notVendored: new Set() });

/**
 * The one definition of a generated or vendored file, used by every plugin for its source trees and for the paths of
 * its history. A file is generated when `.gitattributes` marks it `linguist-generated` or its first lines carry a
 * generated-code header, and vendored when `.gitattributes` marks it `linguist-vendored` or it lies below a vendor
 * directory. An attribute that is unset or false (`-linguist-generated`, `linguist-vendored=false`) opts the path
 * back in: the header or the directory then does not make it generated or vendored.
 * `entries` are the paths and blobs at the revision. A path with no blob there (deleted since) is decided by the
 * attributes and the directory alone.
 */
export async function classifyFiles(
  repoPath: string,
  ref: string | undefined,
  entries: readonly { path: string; blob?: string | null }[],
  treeFiles: readonly string[],
  options: ClassifyOptions = {},
): Promise<FileClasses> {
  const paths = entries.map((entry) => entry.path);
  let attributes: PathAttributes;
  try {
    attributes = await readPathAttributes(repoPath, ref, paths, treeFiles);
  } catch {
    attributes = noAttributes();
  }
  const vendored = new Set(attributes.vendored);
  for (const path of paths) if (isInVendorDirectory(path) && !attributes.notVendored.has(path)) vendored.add(path);

  const generated = new Set(attributes.generated);
  const candidate = options.headerCandidate ?? maybeText;
  const toRead: HeadSource[] = [];
  for (const { path, blob } of entries) {
    if (generated.has(path) || vendored.has(path) || attributes.notGenerated.has(path)) continue;
    if (typeof blob === "string" && candidate(path)) toRead.push({ path, blob });
  }
  for (const path of await generatedByHeader(repoPath, toRead, options.read)) generated.add(path);
  return { generated, vendored };
}

/** Records the generated and vendored files among `touched` for the `dropped` counts of the command. A generated file is not also counted as vendored. */
export function recordClasses(classes: FileClasses, touched: Iterable<string>): void {
  for (const path of touched) {
    if (classes.generated.has(path)) recordDropped("generated", path);
    else if (classes.vendored.has(path)) recordDropped("vendored", path);
  }
}
